import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import vm from "node:vm";

// Loads the real Files class (as editor-drafts.test.js does) and drives its command loop directly.
function files() {
  const source = readFileSync(new URL("./main.js", import.meta.url), "utf8")
    .replace(/^import .*;$/gm, "").replace("export default class Files", "class Files");
  const scope = { View: class {} };
  vm.runInNewContext(source + "\nglobalThis.Files = Files;", scope);
  return scope.Files;
}

function view(query, hits = { files: [{ path: "a.js", matches: [] }], totalMatches: 1 }) {
  const Files = files();
  const v = Object.create(Files.prototype);
  const log = { focus: 0, rerun: 0 };
  Object.assign(v, {
    view: "files",
    hits,
    q: { value: () => query, focus() { log.focus++; } },
    rerun() { log.rerun++; },
  });
  const cx = { notify() {} };
  return { v, cx, log };
}

test("reveal-search opens Contents, focuses the query, and keeps the existing query and results", async () => {
  const { v, cx, log } = view("needle");
  const hits = v.hits;
  await v.command("reveal-search", cx);
  assert.equal(v.view, "search");
  assert.equal(log.focus, 1);
  assert.equal(log.rerun, 0, "⌘⇧F must not re-run the query");
  assert.equal(v.hits, hits, "existing results are kept as they are");
});

test("reveal-search with an empty query only switches view and focuses", async () => {
  const { v, cx, log } = view("   ", null);
  await v.command("reveal-search", cx);
  assert.equal(v.view, "search");
  assert.equal(log.focus, 1);
  assert.equal(log.rerun, 0);
});

test("search keeps its own behaviour: it re-runs a non-empty query", async () => {
  const { v, cx, log } = view("needle");
  await v.command("search", cx);
  assert.equal(v.view, "search");
  assert.equal(log.focus, 1);
  assert.equal(log.rerun, 1);
});

test("search with an empty query does not re-run", async () => {
  const { v, cx, log } = view("", null);
  await v.command("search", cx);
  assert.equal(log.rerun, 0);
});

